from __future__ import annotations

import base64
import shutil
import subprocess
import sys
from datetime import datetime
from pathlib import Path

ROOT = Path(r"C:\Users\hrhar\Project\granitemeasure-ai")
MOBILE = ROOT / "mobile"
VOICE_FILE = MOBILE / "lib" / "granite-voice.ts"
SCREEN_FILE = MOBILE / "app" / "ai-assistant.tsx"
BLOCK_FILE = MOBILE / "app" / "blocks" / "[id].tsx"
MARKER = "GRANITE_MOBILE_AI_ENTRY_V1"

VOICE_B64 = ""
SCREEN_B64 = ""


def backup(path: Path) -> None:
    if not path.exists():
        return
    stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    target = path.with_name(f"{path.name}.backup-{stamp}")
    shutil.copy2(path, target)
    print(f"[BACKUP] {target}")


def write_embedded(path: Path, payload: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    backup(path)
    path.write_bytes(base64.b64decode(payload.encode("ascii")))
    print(f"[OK] Wrote {path}")


def patch_block_detail() -> None:
    if not BLOCK_FILE.exists():
        raise SystemExit(f"[ERROR] Missing block detail: {BLOCK_FILE}")

    text = BLOCK_FILE.read_text(encoding="utf-8")
    if MARKER in text:
        print("[OK] Block Detail AI entry already installed.")
        return

    anchor = '''        {error ? (
          <Animated.View entering={FadeInDown.duration(280)} style={styles.errorCard}>'''

    if anchor not in text:
        raise SystemExit(
            "[ERROR] Could not find the current Block Detail insertion anchor. "
            "No Block Detail changes were made."
        )

    entry = '''        {/* GRANITE_MOBILE_AI_ENTRY_V1 */}
        <Animated.View
          entering={FadeInDown.delay(70).duration(340)}
          style={styles.aiAssistantEntry}
        >
          <Pressable
            onPress={() => {
              if (!blockId) return;
              const code = block?.block_code || "";
              router.push(
                `/ai-assistant?blockId=${encodeURIComponent(blockId)}&blockCode=${encodeURIComponent(code)}`,
              );
            }}
            style={({ pressed }) => [
              styles.aiAssistantEntryPress,
              pressed && styles.pressed,
            ]}
          >
            <View style={styles.aiAssistantOrb}>
              <Text style={styles.aiAssistantOrbText}>AI</Text>
            </View>
            <View style={styles.flexOne}>
              <Text style={styles.aiAssistantEyebrow}>
                {language === "te" ? "తెలుగు వాయిస్ AI" : "GRANITE VOICE AI"}
              </Text>
              <Text style={styles.aiAssistantTitle}>
                {language === "te"
                  ? "ఈ బ్లాక్ గురించి మాట్లాడి అడగండి"
                  : "Talk to AI about this block"}
              </Text>
              <Text style={styles.aiAssistantSubtitle}>
                {language === "te"
                  ? "కొలతలు · 3D · లోపాలు · కట్టింగ్ · వేస్టేజ్"
                  : "Measurements · 3D · defects · cutting · wastage"}
              </Text>
            </View>
            <Text style={styles.aiAssistantArrow}>›</Text>
          </Pressable>
        </Animated.View>

'''

    text = text.replace(anchor, entry + anchor, 1)

    close = "\n});\n"
    pos = text.rfind(close)
    if pos < 0:
        raise SystemExit("[ERROR] Could not find StyleSheet closing marker.")

    style_block = '''  aiAssistantEntry: {
    borderRadius: 19,
    overflow: "hidden",
    backgroundColor: "#FFFFFF",
    borderWidth: 1,
    borderColor: "#CFE4E1",
    shadowColor: "#143A45",
    shadowOpacity: 0.06,
    shadowRadius: 12,
    shadowOffset: { width: 0, height: 5 },
    elevation: 3,
  },
  aiAssistantEntryPress: {
    minHeight: 76,
    padding: 12,
    flexDirection: "row",
    alignItems: "center",
    gap: 11,
  },
  aiAssistantOrb: {
    width: 44,
    height: 44,
    borderRadius: 15,
    alignItems: "center",
    justifyContent: "center",
    backgroundColor: "#173B47",
  },
  aiAssistantOrbText: {
    color: "#7CDBC8",
    fontSize: 12,
    fontWeight: "900",
  },
  aiAssistantEyebrow: {
    color: "#15949B",
    fontSize: 7.5,
    fontWeight: "900",
    letterSpacing: 0.8,
  },
  aiAssistantTitle: {
    color: "#25434D",
    fontSize: 11.5,
    lineHeight: 16,
    marginTop: 3,
    fontWeight: "900",
  },
  aiAssistantSubtitle: {
    color: "#809298",
    fontSize: 8,
    lineHeight: 12,
    marginTop: 2,
    fontWeight: "700",
  },
  aiAssistantArrow: {
    color: "#709097",
    fontSize: 25,
    lineHeight: 28,
  },
'''

    patched = text[:pos] + "\n" + style_block + text[pos:]

    backup(BLOCK_FILE)
    BLOCK_FILE.write_text(patched, encoding="utf-8")
    print("[OK] Added Telugu-first AI/voice entry to Block Detail.")


def main() -> int:
    print("GraniteMeasure AI - Telugu-first Expo Voice AI V1")
    print("=" * 72)

    if not MOBILE.exists():
        print(f"[ERROR] Mobile project not found: {MOBILE}")
        return 1

    package_json = MOBILE / "package.json"
    if not package_json.exists():
        print("[ERROR] mobile/package.json is missing.")
        return 1

    package_text = package_json.read_text(encoding="utf-8")
    if '"expo-audio"' not in package_text:
        print("[ERROR] expo-audio is not installed in mobile/package.json.")
        return 1

    print("[OK] expo-audio dependency detected.")
    write_embedded(VOICE_FILE, VOICE_B64)
    write_embedded(SCREEN_FILE, SCREEN_B64)
    patch_block_detail()

    print("\nRunning TypeScript validation...")
    npx = "npx.cmd" if sys.platform.startswith("win") else "npx"
    result = subprocess.run([npx, "tsc", "--noEmit"], cwd=MOBILE)

    if result.returncode != 0:
        print("\n[FAILED] TypeScript reported errors. Send the complete output.")
        return result.returncode

    print("\n[OK] npx tsc --noEmit passed.")
    print("[OK] Native Expo microphone recording connected.")
    print("[OK] Telugu is the default assistant language when no preference exists.")
    print("[OK] Text chat uses the block-grounded AI endpoint.")
    print("[OK] Voice chat uses the existing Whisper-backed block voice endpoint.")
    print("[OK] Reply playback uses backend Telugu/English TTS with expo-audio.")
    print("[OK] Block Detail opens AI with the exact block id/context.")
    print("[OK] The UI never turns a 90% target into a validated claim unless target_met is true.")
    print("\nNext command:")
    print("cd mobile")
    print("npx expo start --clear --lan")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
